//! Reúne únicamente originales explícitos y comprueba identidad de las copias.
use std::{fs,path::Path,io::Write};
fn copy(src:&Path,dst:&Path)->Result<(),Box<dyn std::error::Error>>{let base=std::env::current_dir()?.canonicalize()?;if !dst.parent().unwrap().canonicalize()?.starts_with(&base){return Err("Destino exterior".into())}let b=fs::read(src)?;let mut f=fs::OpenOptions::new().create_new(true).write(true).open(dst)?;f.write_all(&b)?;f.sync_all()?;if fs::read(dst)?!=b{return Err("Copia discordante".into())}println!("COPIA_COTEJADA {} {}",dst.display(),b.len());Ok(())}
fn main()->Result<(),Box<dyn std::error::Error>>{let old=Path::new("./antecedentes/entrega-09");let new=Path::new("./seguimiento/instruct-v7");let dst=std::env::current_dir()?;if dst!=new.join("entrega-09"){return Err("Sede no autorizada".into())}
for name in ["EVIDENCIAS-V7.tar.gz","TRAZA-EXPERTOS-V7.tar.gz.parte-001","TRAZA-EXPERTOS-V7.tar.gz.parte-002","INDICE-EVIDENCIAS-V7.tsv","EVIDENCIAS-SEGMENTO-02.tar.gz","TRAZA-SEGMENTO-02.tar.gz","INDICE-SEGMENTO-02.tsv","PREPARACION-P09.tar.gz","PREPARACION-CONTEXTO.tar.gz","CONTROL-09-preparacion.tar.gz","CONTROL-09-revision-02.tar.gz","CONTROL-09-revision-03.tar.gz","FUENTES-V6.tar.gz","FUENTES-PRE-ADENDA-P09.tar.gz","FUENTES-ADENDA-P09.tar.gz","DIFERENCIAS-CALCULO.patch","DIFERENCIAS-SUPERVISOR.patch","ENCARGO-CANONICO.md","ADENDA-RECUPERACION-P09-20260930.md","AUTORIZACION-POSTERIOR-20260930.md","PROTOCOLO-BANCO.md","preguntas.json","MAPA-PAGINAS.json","INDICE-PAGINAS.json","PAGINAS-MCP.json","custodia-final-v7.rs","custodia-final-v7.exe"]{copy(&old.join(name),&dst.join(name))?;}
for name in ["EVIDENCIAS-SEGMENTO-03.tar.gz","TRAZA-SEGMENTO-03.tar.gz","INDICE-SEGMENTO-03.tsv","EVIDENCIAS-SEGMENTO-04.tar.gz","TRAZA-SEGMENTO-04.tar.gz","INDICE-SEGMENTO-04.tsv","EVIDENCIAS-SEGMENTO-05.tar.gz","TRAZA-SEGMENTO-05.tar.gz","INDICE-SEGMENTO-05.tsv","PREPARACION-PARAMETROS.tar.gz","PREPARACION-CONSULTA.tar.gz","REANUDACION-P16.json","REANUDACION-P23.json","AUTORIZACION-HASTA-P25-20260930.md","CIERRE-COMPROBADO.json","cerrar-campana.rs"]{copy(&new.join(name),&dst.join(name))?;}
Ok(())}
